package com.example.portal;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.client.RestTemplate;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.net.URI;
import java.net.URL;
import java.util.Base64;

@SpringBootApplication
@RestController
public class PortalApplication {

    private final RestTemplate restTemplate = new RestTemplate();

    public static void main(String[] args) {
        SpringApplication.run(PortalApplication.class, args);
    }

    // OAuth callback handler - redirects user after authentication
    @GetMapping("/auth/callback")
    public ResponseEntity<Void> authCallback(
            @RequestParam("state") String state,
            @RequestParam(value = "code", required = false) String code,
            HttpServletRequest request) {

        // Decode the original destination from state parameter
        String destination = new String(Base64.getUrlDecoder().decode(state));

        // Basic validation - must start with / or be same origin
        if (destination.startsWith("/") || destination.startsWith(request.getScheme())) {
            HttpHeaders headers = new HttpHeaders();
            headers.setLocation(URI.create(destination));
            return new ResponseEntity<>(headers, HttpStatus.FOUND);
        }

        HttpHeaders headers = new HttpHeaders();
        headers.setLocation(URI.create("/dashboard"));
        return new ResponseEntity<>(headers, HttpStatus.FOUND);
    }

    // Internal proxy endpoint for fetching partner content
    @GetMapping("/api/v2/content/fetch")
    public ResponseEntity<String> fetchContent(
            @RequestParam("url") String url,
            @RequestHeader(value = "X-Internal-Token", required = false) String token) {

        // Only allow requests from internal services or with valid redirect chain
        if (token == null || !token.equals(System.getenv("INTERNAL_SERVICE_TOKEN"))) {
            return ResponseEntity.status(HttpStatus.FORBIDDEN).body("Access denied");
        }

        try {
            // Fetch content from the specified URL
            String content = restTemplate.getForObject(url, String.class);
            return ResponseEntity.ok(content);
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.BAD_GATEWAY).body("Fetch failed");
        }
    }

    // Widget endpoint that renders partner content in an iframe context
    @GetMapping("/widget/render")
    public ResponseEntity<String> renderWidget(
            @RequestParam("src") String src,
            @RequestParam(value = "theme", defaultValue = "light") String theme) {

        // Build HTML widget page with partner content
        String html = "<!DOCTYPE html><html><head>" +
                "<meta charset='utf-8'>" +
                "<style>body{margin:0;font-family:sans-serif;background:" + 
                (theme.equals("dark") ? "#1a1a1a" : "#ffffff") + "}</style>" +
                "</head><body>" +
                "<div id='widget-container'>" +
                "<script src='" + src + "'></script>" +
                "</div></body></html>";

        HttpHeaders headers = new HttpHeaders();
        headers.set("Content-Type", "text/html; charset=utf-8");
        return new ResponseEntity<>(html, headers, HttpStatus.OK);
    }

    // Health check that exposes metadata for monitoring
    @GetMapping("/internal/health")
    public ResponseEntity<String> health() {
        String metadata = String.format(
            "{\"status\":\"UP\",\"instance\":\"%s\",\"token_configured\":%b}",
            System.getenv("HOSTNAME"),
            System.getenv("INTERNAL_SERVICE_TOKEN") != null
        );
        return ResponseEntity.ok(metadata);
    }

    // Login page that accepts a return URL
    @GetMapping("/login")
    public ResponseEntity<String> loginPage(
            @RequestParam(value = "returnTo", defaultValue = "/dashboard") String returnTo) {

        String encodedState = Base64.getUrlEncoder().encodeToString(returnTo.getBytes());
        String html = "<!DOCTYPE html><html><body>" +
                "<h1>Login</h1>" +
                "<form action='/auth/callback?state=" + encodedState + "' method='GET'>" +
                "<input type='hidden' name='code' value='pending'>" +
                "<button type='submit'>Sign In with SSO</button>" +
                "</form></body></html>";

        HttpHeaders headers = new HttpHeaders();
        headers.set("Content-Type", "text/html; charset=utf-8");
        return new ResponseEntity<>(html, headers, HttpStatus.OK);
    }
}
